    LandPresetProfile GetProfile(int i){if(landPresetProfiles==null||landPresetProfiles.Length!=6)ApplyDefaultProfiles(); return landPresetProfiles[math.clamp(i,0,landPresetProfiles.Length-1)];}
    public void SetInputs(MenuPlanetPreviewWorldInputs v) => inputs = v; public void RequestRebuild(PreviewWorldRebuildScope scope, bool immediate = false) { pending |= ExpandDependencies(scope); if (immediate) Flush(); else scheduledAt = Time.time + regenerationDelay; }
    void Update() { if (scheduledAt > 0 && Time.time >= scheduledAt) Flush(); }
    void Flush() { scheduledAt = -1; var s = pending; pending = PreviewWorldRebuildScope.None; if (s == PreviewWorldRebuildScope.None) return; if ((s & PreviewWorldRebuildScope.Tectonics) != 0) GenerateTectonics(); if ((s & PreviewWorldRebuildScope.Climate) != 0) GenerateClimate(); if ((s & PreviewWorldRebuildScope.Hydrology) != 0) GenerateHydrology(); if ((s & PreviewWorldRebuildScope.Biomes) != 0) GenerateBiomes(); WorldTexturesUpdated?.Invoke(); }
    PreviewWorldRebuildScope ExpandDependencies(PreviewWorldRebuildScope r) => (r & PreviewWorldRebuildScope.Tectonics) != 0 ? PreviewWorldRebuildScope.All : (r & PreviewWorldRebuildScope.Climate) != 0 ? PreviewWorldRebuildScope.Climate | PreviewWorldRebuildScope.Hydrology | PreviewWorldRebuildScope.Biomes : (r & PreviewWorldRebuildScope.Hydrology) != 0 ? PreviewWorldRebuildScope.Hydrology | PreviewWorldRebuildScope.Biomes : (r & PreviewWorldRebuildScope.Biomes) != 0 ? PreviewWorldRebuildScope.Biomes : 0;
    void Ensure(ref Texture2D t, string n) { if (t != null && t.width == mapWidth && t.height == mapHeight) return; if (t != null) Destroy(t); t = new Texture2D(mapWidth, mapHeight, TextureFormat.RGBA32, false, true) { name = n, wrapMode = TextureWrapMode.Repeat, filterMode = FilterMode.Bilinear }; }
    static byte ToByte(float v) => (byte)math.clamp(math.round(math.saturate(v) * 255f), 0, 255);
    void GenerateTectonics(){Ensure(ref tectonicSurfaceTexture,"MenuTectonicSurface");Ensure(ref tectonicBoundaryTexture,"MenuTectonicBoundary");Ensure(ref tectonicCrustTexture,"MenuTectonicCrust"); int n=mapWidth*mapHeight; var s=new NativeArray<Color32>(n,Allocator.TempJob); var b=new NativeArray<Color32>(n,Allocator.TempJob); var c=new NativeArray<Color32>(n,Allocator.TempJob);
        var profile=GetProfile(inputs.landPresetIndex); var plates=new NativeArray<PreviewTectonicPlateNative>(plateCount,Allocator.TempJob); var seeds=BuildContinentSkeletonNodes(profile,Allocator.TempJob,out int groupCount); var carvers=BuildCoastCarvers(profile,seeds,groupCount,Allocator.TempJob); var raw=new NativeArray<RawTectonicPixel>(n,Allocator.TempJob); BuildPlates(plates);
        float desiredCoverage=math.lerp(profile.maxLandCoverage,profile.minLandCoverage,math.saturate(inputs.landThreshold));
        if(logPresetDiagnostics||logContinentSkeletonDiagnostics){Debug.Log($"[MenuPlanetPreviewWorldGenerator] Preset={profile.name} | Groups={groupCount} | SkeletonNodes={seeds.Length} | Carvers={carvers.Length} | TargetCoverage={(desiredCoverage*100f):F1}% | ThresholdInput={inputs.landThreshold:F2}");}
        new TectRawJob{width=mapWidth,height=mapHeight,seed=inputs.seed,landScale=math.max(0.1f,inputs.landScale),elevation=inputs.elevation,plateBoundaryWidth=plateBoundaryWidth,plateShapeNoiseStrength=plateShapeNoiseStrength,plateBoundaryWarpScale=plateBoundaryWarpScale,plateBoundaryWarpAmplitude=plateBoundaryWarpAmplitude,continentalElevationStrength=continentalElevationStrength,oceanBasinDepthStrength=oceanBasinDepthStrength,convergentMountainStrength=convergentMountainStrength,divergentRidgeStrength=divergentRidgeStrength,terrainDetailNoiseStrength=terrainDetailNoiseStrength,continentalShelfStrength=continentalShelfStrength,continentalShelfWidth=continentalShelfWidth,continentalDetailScale=continentalDetailScale,coastlineDetailStrength=profile.coastlineNoiseStrength,plateContinentalInfluence=plateContinentalInfluence,islandFragmentStrength=profile.islandFragmentStrength,continentDomainWarpScale=continentDomainWarpScale,continentDomainWarpStrength=continentDomainWarpStrength,profileDomainWarpMultiplier=profile.domainWarpMultiplier,plates=plates,continentSeeds=seeds,coastCarvers=carvers,raw=raw}.Schedule(n,128).Complete();
        float preliminaryShapeThreshold=ComputeCoverageThreshold(raw,desiredCoverage);
        new TectCoastlineFractalRefineJob{width=mapWidth,height=mapHeight,seed=inputs.seed,preliminaryShapeThreshold=preliminaryShapeThreshold,coastlineFractalStrength=coastlineFractalStrength*profile.coastlineFractalMultiplier,coastlineFractalBandWidth=coastlineFractalBandWidth,coastlineFractalMacroScale=coastlineFractalMacroScale,coastlineFractalMidScale=coastlineFractalMidScale,coastlineFractalFineScale=coastlineFractalFineScale,coastlineFractalRidgedMix=coastlineFractalRidgedMix,raw=raw}.Schedule(n,128).Complete();
        float finalShapeThreshold=ComputeCoverageThreshold(raw,desiredCoverage);
        new TectFinalizeJob{shapeThreshold=finalShapeThreshold,coastlineSoftness=coastlineSoftness,raw=raw,surf=s,bound=b,crust=c}.Schedule(n,128).Complete();
        tectonicSurfaceTexture.SetPixelData(s,0);tectonicBoundaryTexture.SetPixelData(b,0);tectonicCrustTexture.SetPixelData(c,0);tectonicSurfaceTexture.Apply(false,false);tectonicBoundaryTexture.Apply(false,false);tectonicCrustTexture.Apply(false,false);s.Dispose();b.Dispose();c.Dispose();plates.Dispose();seeds.Dispose();carvers.Dispose();
        if(logLandCoverageDiagnostics||logContinentSkeletonDiagnostics){float landPx=0;for(int i=0;i<n;i++)landPx+=raw[i].continentalShapeScore>=finalShapeThreshold?1f:0f;Debug.Log($"[MenuPlanetPreviewWorldGenerator] Preset={profile.name} | Groups={groupCount} | SkeletonNodes={seeds.Length} | Carvers={carvers.Length} | DesiredLandCoverage={(desiredCoverage*100f):F1}% | ActualLandCoverage={(landPx/n*100f):F1}% | PreFractalThreshold={preliminaryShapeThreshold:F4} | FinalThreshold={finalShapeThreshold:F4}");}
        raw.Dispose(); RebuildContinentality(); }
    NativeArray<PreviewContinentSeedNative> BuildContinentSkeletonNodes(LandPresetProfile profile,Allocator a,out int groupCount){ var rng=new Unity.Mathematics.Random((uint)math.max(1,(int)(inputs.seed*1000)+12345)); var groupRoots=new List<float3>(); groupCount=profile.forceSinglePangaeaGroup?1:rng.NextInt(profile.minContinentGroupCount,profile.maxContinentGroupCount+1); for(int g=0; g<groupCount; g++){ float3 best=math.normalizesafe(rng.NextFloat3Direction()); float bestScore=-1f; for(int t=0;t<64;t++){ float3 cand=math.normalizesafe(rng.NextFloat3Direction()); float sep=MinSeparationDot(cand,groupRoots); if(groupRoots.Count==0||sep<=math.cos(math.radians(profile.minGroupSeparationDegrees))){best=cand;break;} if(groupRoots.Count==0||-sep>bestScore){bestScore=-sep;best=cand;} } groupRoots.Add(best);} var list=new List<PreviewContinentSeedNative>(); for(int g=0; g<groupRoots.Count; g++){ float3 center=groupRoots[g]; float3 tangent=RandomTangentAt(center,ref rng); int mainNodes=rng.NextInt(profile.minMainChainNodes,profile.maxMainChainNodes+1); var mainCenters=new List<float3>(); for(int i=0;i<mainNodes;i++){ mainCenters.Add(center); list.Add(new PreviewContinentSeedNative{groupId=g,centerDir=center,radius=rng.NextFloat(profile.minNodeRadius,profile.maxNodeRadius),strength=rng.NextFloat(profile.minNodeStrength,profile.maxNodeStrength),elongation=rng.NextFloat(0.15f,0.55f),stretchAxis=tangent}); StepAlongSphere(ref center,ref tangent,rng.NextFloat(profile.minNodeStepDegrees,profile.maxNodeStepDegrees),ref rng);} int branches=rng.NextInt(profile.minBranchCountPerGroup,profile.maxBranchCountPerGroup+1); for(int b=0;b<branches;b++){ float3 bCenter=mainCenters[rng.NextInt(0,mainCenters.Count)]; float3 bTan=RandomTangentAt(bCenter,ref rng); int bn=rng.NextInt(profile.minBranchNodes,profile.maxBranchNodes+1); for(int n=0;n<bn;n++){ list.Add(new PreviewContinentSeedNative{groupId=g,centerDir=bCenter,radius=rng.NextFloat(profile.minNodeRadius*0.65f,profile.maxNodeRadius*0.9f),strength=rng.NextFloat(profile.minNodeStrength*0.8f,profile.maxNodeStrength),elongation=rng.NextFloat(0.2f,0.6f),stretchAxis=bTan}); StepAlongSphere(ref bCenter,ref bTan,rng.NextFloat(profile.branchStepDegreesMin,profile.branchStepDegreesMax),ref rng);} } } var arr=new NativeArray<PreviewContinentSeedNative>(list.Count,a); for(int i=0;i<list.Count;i++)arr[i]=list[i]; return arr;}
    NativeArray<PreviewCoastCarverNative> BuildCoastCarvers(LandPresetProfile profile,NativeArray<PreviewContinentSeedNative> nodes,int groupCount,Allocator a){ var rng=new Unity.Mathematics.Random((uint)math.max(1,(int)(inputs.seed*3000)+2222)); var list=new List<PreviewCoastCarverNative>(); for(int g=0;g<groupCount;g++){ int cnt=rng.NextInt(profile.minCoastCarversPerGroup,profile.maxCoastCarversPerGroup+1); for(int i=0;i<cnt;i++){ int anchor=-1; for(int t=0;t<32;t++){ int idx=rng.NextInt(0,nodes.Length); if(nodes[idx].groupId==g){anchor=idx;break;}} if(anchor<0) continue; var n=nodes[anchor]; float3 tangent=RandomTangentAt(n.centerDir,ref rng); float ang=math.radians(rng.NextFloat(10f,35f)); float3 center=math.normalizesafe(n.centerDir*math.cos(ang)+tangent*math.sin(ang)); list.Add(new PreviewCoastCarverNative{centerDir=center,radius=rng.NextFloat(profile.minCarverRadius,profile.maxCarverRadius),strength=rng.NextFloat(profile.minCarverStrength,profile.maxCarverStrength),elongation=rng.NextFloat(0.1f,0.7f),stretchAxis=tangent}); }} var arr=new NativeArray<PreviewCoastCarverNative>(list.Count,a); for(int i=0;i<list.Count;i++)arr[i]=list[i]; return arr;}
    static float3 RandomTangentAt(float3 normal,ref Unity.Mathematics.Random rng){ float3 v=math.normalizesafe(rng.NextFloat3Direction()); float3 t=v-normal*math.dot(v,normal); if(math.lengthsq(t)<1e-5f) t=math.cross(normal,new float3(0,1,0)); return math.normalizesafe(t,new float3(1,0,0)); }
    static float MinSeparationDot(float3 candidate,List<float3> roots){ float min=1f; foreach(var r in roots) min=math.min(min,math.dot(candidate,r)); return min; }
    static void StepAlongSphere(ref float3 center,ref float3 tangent,float stepDeg,ref Unity.Mathematics.Random rng){ float stepRad=math.radians(stepDeg); float3 next=math.normalizesafe(center*math.cos(stepRad)+tangent*math.sin(stepRad)); float3 proj=tangent-next*math.dot(tangent,next); float3 side=math.cross(next,proj); proj=math.normalizesafe(proj+side*rng.NextFloat(-0.35f,0.35f)); center=next; tangent=math.normalizesafe(proj,new float3(1,0,0)); }
    void BuildPlates(NativeArray<PreviewTectonicPlateNative> plates){var rng=new Unity.Mathematics.Random((uint)math.max(1,(int)(inputs.seed*2000)+9871)); for(int i=0;i<plates.Length;i++) plates[i]=new PreviewTectonicPlateNative{centerDir=math.normalizesafe(rng.NextFloat3Direction()),motionDir=math.normalizesafe(rng.NextFloat3Direction()),continentalBias=rng.NextFloat()<continentalPlateFraction?rng.NextFloat(0.55f,1f):rng.NextFloat(0f,0.45f),ruggedness=rng.NextFloat(0.3f,1f),age=rng.NextFloat(),baseElevationBias=rng.NextFloat(-0.1f,0.1f)}; }
    float ComputeCoverageThreshold(NativeArray<RawTectonicPixel> raw,float desiredLandCoverage){const int bins=512; float min=float.MaxValue,max=float.MinValue; for(int i=0;i<raw.Length;i++){var v=raw[i].continentalShapeScore; min=math.min(min,v); max=math.max(max,v);} if(max-min<1e-6f) return min; var hist=new int[bins]; for(int i=0;i<raw.Length;i++){int bi=(int)math.clamp((raw[i].continentalShapeScore-min)/(max-min)*(bins-1),0,bins-1); hist[bi]++;} int target=(int)math.round(math.saturate(desiredLandCoverage)*raw.Length); int acc=0; for(int bi=bins-1;bi>=0;bi--){acc+=hist[bi]; if(acc>=target) return math.lerp(min,max,(float)bi/(bins-1));} return min;}
    void RebuildContinentality(){int n=mapWidth*mapHeight;if(continentality.IsCreated)continentality.Dispose();continentality=new NativeArray<float>(n,Allocator.Persistent);var q=new Queue<int>();var raw=tectonicSurfaceTexture.GetRawTextureData<Color32>();for(int i=0;i<n;i++){if(raw[i].r<128){continentality[i]=0;q.Enqueue(i);}else continentality[i]=9999;}while(q.Count>0){int i=q.Dequeue();int x=i%mapWidth,y=i/mapWidth;float d=continentality[i]+1;int l=y*mapWidth+((x-1+mapWidth)%mapWidth),r=y*mapWidth+((x+1)%mapWidth);if(d<continentality[l]){continentality[l]=d;q.Enqueue(l);}if(d<continentality[r]){continentality[r]=d;q.Enqueue(r);}if(y>0){int u=i-mapWidth;if(d<continentality[u]){continentality[u]=d;q.Enqueue(u);}}if(y<mapHeight-1){int dn=i+mapWidth;if(d<continentality[dn]){continentality[dn]=d;q.Enqueue(dn);}}}float max=1;for(int i=0;i<n;i++)if(continentality[i]>max&&continentality[i]<9999)max=continentality[i];for(int i=0;i<n;i++)continentality[i]=math.saturate(continentality[i]/max);}    
    void GenerateClimate(){if(tectonicSurfaceTexture==null)return; Ensure(ref climateTexture,"MenuClimate"); int n=mapWidth*mapHeight; var tect=new NativeArray<Color32>(tectonicSurfaceTexture.GetRawTextureData<Color32>().ToArray(),Allocator.TempJob); var outp=new NativeArray<Color32>(n,Allocator.TempJob); new ClimateJob{width=mapWidth,height=mapHeight,seed=inputs.seed,temperature=inputs.temperature,moisture=inputs.moisture,moistureResponseScale=inputs.moistureResponseScale,temperatureHumidityInfluence=inputs.temperatureHumidityInfluence,climateNoiseStrength=inputs.climateNoiseStrength,coastWetnessStrength=inputs.coastWetnessStrength,continentalDrynessStrength=inputs.continentalDrynessStrength,continentalTemperatureStrength=inputs.continentalTemperatureStrength,rainShadowStrength=inputs.rainShadowStrength,orographicWetnessStrength=inputs.orographicWetnessStrength,orographicSampleOffset=math.max(1f,inputs.orographicSampleOffset*mapWidth),seasonalityStrength=inputs.seasonalityStrength,tect=tect,cont=continentality,outp=outp}.Schedule(n,128).Complete(); climateTexture.SetPixelData(outp,0); climateTexture.Apply(false,false); tect.Dispose(); outp.Dispose(); }
    void GenerateHydrology(){if(tectonicSurfaceTexture==null||climateTexture==null){Debug.LogError("[MenuPlanetPreviewWorldGenerator] Missing tectonic or climate data; hydrology generation aborted."); return;} Ensure(ref hydrologyMaskTexture,"MenuHydrology");
        int n=mapWidth*mapHeight; var land=new float[n];var h=new float[n];var mountain=new float[n];var shelf=new float[n];var rain=new float[n];var river=new float[n];var lake=new float[n];var flow=new float[n];var wet=new float[n];var depth=new float[n]; var t=tectonicSurfaceTexture.GetRawTextureData<Color32>(); var cl=climateTexture.GetRawTextureData<Color32>();
        for(int i=0;i<n;i++){land[i]=t[i].r/255f;h[i]=t[i].g/255f;mountain[i]=t[i].b/255f;shelf[i]=t[i].a/255f;rain[i]=cl[i].g/255f;} var src=PickSources(land,h,mountain,shelf,rain); foreach(var s in src) TraceRiver(s,land,h,shelf,river,lake,flow,wet,depth); BuildWetlands(land,h,river,lake,wet,rain); Blur(river);Blur(lake);Blur(wet);Blur(depth); var px=new Color32[n];for(int i=0;i<n;i++)px[i]=new Color32(ToByte(river[i]),ToByte(lake[i]),ToByte(wet[i]),ToByte(depth[i])); hydrologyMaskTexture.SetPixels32(px); hydrologyMaskTexture.Apply(false,false);}    
    
    void StampDelta(int mouth,int prev,float flowAmt,float[] land,float[] river,float[] wet,float[] depth){ if(mouth<0||mouth>=land.Length||prev<0||prev>=land.Length||land[mouth]>=0.5f) return; int mx=mouth%mapWidth,my=mouth/mapWidth,px=prev%mapWidth,py=prev/mapWidth; int dx=mx-px; if(dx>mapWidth/2)dx-=mapWidth; if(dx<-mapWidth/2)dx+=mapWidth; int dy=my-py; float len=Mathf.Max(1f,Mathf.Sqrt(dx*dx+dy*dy)); float dirX=dx/len,dirY=dy/len; float fan=Mathf.Lerp(2f,5f,Mathf.Clamp01(flowAmt/10f)); for(int fy=-6;fy<=6;fy++) for(int fx=-6;fx<=6;fx++){ int xx=(mx+fx+mapWidth)%mapWidth; int yy=Mathf.Clamp(my+fy,0,mapHeight-1); int idx=yy*mapWidth+xx; float r=Mathf.Sqrt(fx*fx+fy*fy); if(r>fan) continue; float along=(fx*dirX+fy*dirY); if(along<-1.5f) continue; float lateral=Mathf.Abs(fx*(-dirY)+fy*dirX); float w=Mathf.Clamp01(1f-r/(fan+0.001f))*Mathf.Clamp01(1f-lateral/(fan*0.85f+0.001f)); river[idx]=Mathf.Max(river[idx],w*Mathf.Lerp(0.45f,0.9f,Mathf.Clamp01(flowAmt/12f))); wet[idx]=Mathf.Max(wet[idx],w*0.85f); depth[idx]=Mathf.Max(depth[idx],w*0.65f); }}

    List<int> PickSources(float[] land,float[] h,float[] mountain,float[] shelf,float[] rainfall){int target=inputs.waterwaysPreset==0?16:inputs.waterwaysPreset==1?34:68; var c=new List<int>(); for(int y=16;y<mapHeight-16;y+=3)for(int x=0;x<mapWidth;x+=3){int i=y*mapWidth+x; if(land[i]<0.6f||h[i]<0.35f||shelf[i]>0.2f)continue; float s=h[i]*0.45f+mountain[i]*0.20f+rainfall[i]*0.35f; if(s>0.5f)c.Add(i);} c.Sort((a,b)=>h[b].CompareTo(h[a])); var o=new List<int>(); foreach(var i in c){bool near=false;int x=i%mapWidth,y=i/mapWidth;foreach(var k in o){int ox=k%mapWidth,oy=k/mapWidth;if(Mathf.Abs(ox-x)+Mathf.Abs(oy-y)<24){near=true;break;}} if(!near){o.Add(i); if(o.Count>=target)break;}} return o;}
    bool TraceRiver(int src,float[] land,float[] h,float[] shelf,float[] river,float[] lake,float[] flow,float[] wet,float[] depth){var vis=new HashSet<int>(); int cur=src,prev=src; for(int step=0;step<900;step++){if(!vis.Add(cur))break; int x=cur%mapWidth,y=cur/mapWidth; float fv=flow[cur]+1f; float width=Mathf.Lerp(1f,4.8f,Mathf.Clamp01(fv/8f+step/650f)); Stamp(river,x,y,width,Mathf.Lerp(0.5f,0.95f,inputs.moisture)); Stamp(depth,x,y,Mathf.Lerp(0.8f,1.2f,width*0.16f),Mathf.Clamp01(0.25f+fv*0.08f+step/1200f)); flow[cur]+=1f; bool reachedOcean=land[cur]<0.5f; bool reachedCoastalShelf=shelf[cur]>0.2f; if(reachedOcean||reachedCoastalShelf){ if(fv>2.5f) StampDelta(cur,prev,fv,land,river,wet,depth); return true; } int best=cur; float bestH=h[cur]; for(int ny=-1;ny<=1;ny++)for(int nx=-1;nx<=1;nx++){if(nx==0&&ny==0)continue; int yy=Mathf.Clamp(y+ny,0,mapHeight-1); int xx=(x+nx+mapWidth)%mapWidth; int ni=yy*mapWidth+xx; if(h[ni]<bestH){bestH=h[ni]; best=ni;}} if(best==cur){Stamp(lake,x,y,3f,0.8f);break;} if(river[best]>0.35f){flow[best]+=flow[cur]+1f;break;} prev=cur;cur=best;} return false;}
    void BuildWetlands(float[] land,float[] h,float[] river,float[] lake,float[] wet,float[] rain){for(int y=0;y<mapHeight;y++)for(int x=0;x<mapWidth;x++){int i=y*mapWidth+x; float nearby=0; for(int ny=-2;ny<=2;ny++)for(int nx=-2;nx<=2;nx++){int yy=Mathf.Clamp(y+ny,0,mapHeight-1);int xx=(x+nx+mapWidth)%mapWidth;int ni=yy*mapWidth+xx; nearby=Mathf.Max(nearby,Mathf.Max(river[ni],lake[ni]));} wet[i]=Mathf.Max(wet[i],nearby*Mathf.Clamp01((0.55f-h[i])*1.8f)*Mathf.Lerp(0.35f,1f,rain[i])*land[i]*0.75f);}}
    void Stamp(float[] buf,int cx,int cy,float rad,float str){int r=Mathf.CeilToInt(rad); for(int y=-r;y<=r;y++){int yy=Mathf.Clamp(cy+y,0,mapHeight-1); for(int x=-r;x<=r;x++){float d=Mathf.Sqrt(x*x+y*y)/Mathf.Max(0.001f,rad); if(d>1)continue; int xx=(cx+x+mapWidth)%mapWidth; int i=yy*mapWidth+xx; buf[i]=Mathf.Max(buf[i],(1f-d*d)*str); }}}
    void Blur(float[] b){var t=new float[b.Length];for(int y=0;y<mapHeight;y++)for(int x=0;x<mapWidth;x++){float s=0;int c=0;for(int ny=-1;ny<=1;ny++)for(int nx=-1;nx<=1;nx++){int yy=Mathf.Clamp(y+ny,0,mapHeight-1);int xx=(x+nx+mapWidth)%mapWidth;s+=b[yy*mapWidth+xx];c++;}t[y*mapWidth+x]=s/c;}System.Array.Copy(t,b,b.Length);}    
    void GenerateBiomes(){ if(tectonicSurfaceTexture==null||climateTexture==null||hydrologyMaskTexture==null)return; Ensure(ref biomeWeights0Texture,"MenuBiome0");Ensure(ref biomeWeights1Texture,"MenuBiome1");Ensure(ref biomeWeights2Texture,"MenuBiome2"); int n=mapWidth*mapHeight; var tect=new NativeArray<Color32>(tectonicSurfaceTexture.GetRawTextureData<Color32>().ToArray(),Allocator.TempJob);var climate=new NativeArray<Color32>(climateTexture.GetRawTextureData<Color32>().ToArray(),Allocator.TempJob);var hydro=new NativeArray<Color32>(hydrologyMaskTexture.GetRawTextureData<Color32>().ToArray(),Allocator.TempJob);var o0=new NativeArray<Color32>(n,Allocator.TempJob);var o1=new NativeArray<Color32>(n,Allocator.TempJob);var o2=new NativeArray<Color32>(n,Allocator.TempJob); new BiomeJob{tect=tect,climate=climate,hydro=hydro,o0=o0,o1=o1,o2=o2,width=mapWidth,height=mapHeight,seed=inputs.seed,biomeProvinceStrength=inputs.biomeProvinceStrength,biomeCompetitionSharpness=math.max(0.5f,inputs.biomeCompetitionSharpness)}.Schedule(n,128).Complete(); biomeWeights0Texture.SetPixelData(o0,0);biomeWeights1Texture.SetPixelData(o1,0);biomeWeights2Texture.SetPixelData(o2,0);biomeWeights0Texture.Apply(false,false);biomeWeights1Texture.Apply(false,false);biomeWeights2Texture.Apply(false,false); tect.Dispose();climate.Dispose();hydro.Dispose();o0.Dispose();o1.Dispose();o2.Dispose(); }
    public void Release(){if(continentality.IsCreated)continentality.Dispose();foreach(var t in new[]{tectonicSurfaceTexture,tectonicBoundaryTexture,tectonicCrustTexture,climateTexture,hydrologyMaskTexture,biomeWeights0Texture,biomeWeights1Texture,biomeWeights2Texture}) if(t!=null)Destroy(t);tectonicSurfaceTexture=null;tectonicBoundaryTexture=null;tectonicCrustTexture=null;climateTexture=null;hydrologyMaskTexture=null;biomeWeights0Texture=null;biomeWeights1Texture=null;biomeWeights2Texture=null;pending=PreviewWorldRebuildScope.None;scheduledAt=-1f;}    
    [BurstCompile] struct TectRawJob:IJobParallelFor{ public int width,height; public float seed,landScale,elevation,plateBoundaryWidth,plateShapeNoiseStrength,plateBoundaryWarpScale,plateBoundaryWarpAmplitude,continentalElevationStrength,oceanBasinDepthStrength,convergentMountainStrength,divergentRidgeStrength,terrainDetailNoiseStrength,continentalShelfStrength,continentalShelfWidth,continentalDetailScale,coastlineDetailStrength,plateContinentalInfluence,islandFragmentStrength,continentDomainWarpScale,continentDomainWarpStrength,profileDomainWarpMultiplier; [ReadOnly] public NativeArray<PreviewTectonicPlateNative> plates; [ReadOnly] public NativeArray<PreviewContinentSeedNative> continentSeeds; [ReadOnly] public NativeArray<PreviewCoastCarverNative> coastCarvers; public NativeArray<RawTectonicPixel> raw; public void Execute(int index){int x=index%width,y=index/width; float3 d=TexelToDir(x,y,width,height); int p0=-1,p1=-1;float b0=-10,b1=-10;for(int p=0;p<plates.Length;p++){float w=(Fbm(d*plateBoundaryWarpScale+new float3(seed*0.013f+p*11.71f,seed*0.021f+p*7.37f,seed*0.017f+p*19.19f))-0.5f)*plateShapeNoiseStrength*plateBoundaryWarpAmplitude; float s=math.dot(d,plates[p].centerDir)+w; if(s>b0){b1=b0;p1=p0;b0=s;p0=p;} else if(s>b1){b1=s;p1=p;}} float delta=b0-b1; float boundary=1f-math.saturate(delta/math.max(1e-4f,plateBoundaryWidth)); var A=plates[p0]; var B=plates[math.max(0,p1)]; float3 bdir=math.normalizesafe(B.centerDir-A.centerDir,new float3(1,0,0)); float along=math.dot(A.motionDir-B.motionDir,bdir); float conv=math.saturate(-along*0.9f)*boundary; float div=math.saturate(along*0.9f)*boundary; float blend=math.saturate((b0-b1)/math.max(1e-4f,plateBoundaryWidth*2f)); float pBias=math.lerp(B.continentalBias,A.continentalBias,blend); float cNoise=Fbm(d*continentalDetailScale+new float3(seed+3.1f,seed*0.71f,seed*1.31f)); float iNoise=Fbm(d*continentalDetailScale*2.6f+new float3(seed+71.3f,seed+18.2f,seed+91.1f)); float3 warp=new float3(Fbm(d*continentDomainWarpScale+new float3(seed+10.7f,seed+20.1f,seed+30.2f)),Fbm(d*continentDomainWarpScale+new float3(seed+40.8f,seed+50.3f,seed+60.4f)),Fbm(d*continentDomainWarpScale+new float3(seed+70.5f,seed+80.9f,seed+90.6f)))-0.5f; float3 warpedDir=math.normalizesafe(d+warp*(continentDomainWarpStrength*profileDomainWarpMultiplier),d); float invProd=1f; for(int i=0;i<continentSeeds.Length;i++){var c=continentSeeds[i]; float sim=math.dot(warpedDir,c.centerDir); float axis=math.dot(warpedDir,c.stretchAxis); float st=math.lerp(1f,1f+c.elongation*math.abs(axis),0.5f); float dist=(1f-sim)/math.max(0.1f,st); float rawV=1f-math.saturate(dist/math.max(1e-4f,c.radius)); float inf=rawV*rawV*(3f-2f*rawV); invProd*=1f-math.saturate(inf*c.strength);} float skeletonBody=1f-invProd; float carveUnion=0f; for(int i=0;i<coastCarvers.Length;i++){var cv=coastCarvers[i]; float sim=math.dot(warpedDir,cv.centerDir); float axis=math.dot(warpedDir,cv.stretchAxis); float st=math.lerp(1f,1f+cv.elongation*math.abs(axis),0.5f); float dist=(1f-sim)/math.max(0.1f,st); float rawV=1f-math.saturate(dist/math.max(1e-4f,cv.radius)); float inf=rawV*rawV*(3f-2f*rawV); carveUnion=math.max(carveUnion,inf*cv.strength);} float carveGate=SmoothThreshold(0.18f,0.88f,skeletonBody); float carvedBody=skeletonBody-carveUnion*carveGate; float shape=carvedBody+(cNoise-0.5f)*coastlineDetailStrength+(pBias-0.5f)*plateContinentalInfluence-(iNoise-0.5f)*islandFragmentStrength+(conv-div)*0.005f; float continental=math.saturate(skeletonBody*0.85f+(pBias*0.15f)); float oceanic=1f-continental; float basin=oceanic*(0.45f+0.55f*Fbm(d*(landScale*2.1f)+new float3(seed+44.1f,seed+12.2f,seed+8.3f)))*oceanBasinDepthStrength; float mountain=math.saturate(conv*(0.5f+continental*0.9f))*(0.6f+0.4f*A.ruggedness); float detail=(Fbm(d*(landScale*3.6f)+new float3(seed+96.2f,seed+51.8f,seed+14.4f))-0.5f)*terrainDetailNoiseStrength; float tectonicRelief=continental*continentalElevationStrength-basin+div*divergentRidgeStrength*oceanic+mountain*convergentMountainStrength+detail+(elevation-0.5f)*0.28f; float shelfProx=math.saturate((continental-oceanic+continentalShelfWidth*2f)/math.max(0.01f,continentalShelfWidth*3f)); raw[index]=new RawTectonicPixel{continentalShapeScore=shape,tectonicReliefHeight=tectonicRelief,mountain=mountain,shelfPotential=shelfProx,boundary=boundary,convergent=conv,divergent=div,continental=continental,oceanic=oceanic,basin=math.saturate(basin),continentalPotential=shape,plateIdNormalized=(float)p0/math.max(1f,plates.Length-1f)};} static float3 TexelToDir(int x,int y,int width,int height){float u=(x+0.5f)/width,v=(y+0.5f)/height;float lon=(u-0.5f)*math.PI*2f,lat=(v-0.5f)*math.PI,cl=math.cos(lat);return new float3(math.cos(lon)*cl,math.sin(lat),math.sin(lon)*cl);} static float SmoothThreshold(float e0,float e1,float x){float t=math.saturate((x-e0)/math.max(1e-6f,e1-e0));return t*t*(3f-2f*t);} static float Fbm(float3 p){float v=0,a=0.5f,f=1;for(int i=0;i<4;i++){float n=noise.snoise(new float3(p.x*f+p.y*0.67f,p.z*f+p.y*0.37f,p.z*0.23f+p.x*0.11f));v+=a*(n*0.5f+0.5f);f*=2;a*=0.5f;}return v;} }

