    [BurstCompile] struct TectFinalizeJob:IJobParallelFor{ public float shapeThreshold,coastlineSoftness; [ReadOnly] public NativeArray<RawTectonicPixel> raw; public NativeArray<Color32> surf,bound,crust; public void Execute(int i){var r=raw[i]; float land=SmoothThreshold(shapeThreshold-coastlineSoftness,shapeThreshold+coastlineSoftness,r.continentalShapeScore); float terrain=math.saturate(r.tectonicReliefHeight*0.8f+0.5f); float landRelief=land*(r.continental*0.6f+r.mountain*0.4f); float oceanRelief=(1f-land)*(-r.basin+r.divergent*0.2f); terrain=math.saturate(terrain+landRelief*0.05f+oceanRelief*0.03f); float shelf=(1f-land)*r.shelfPotential*0.70f*math.saturate(1f-r.basin*1.35f); float normShape=math.saturate((r.continentalShapeScore-shapeThreshold)*0.5f+0.5f); surf[i]=new Color32(ToByte(land),ToByte(terrain),ToByte(r.mountain),ToByte(shelf)); bound[i]=new Color32(ToByte(r.plateIdNormalized),ToByte(r.boundary),ToByte(r.convergent),ToByte(r.divergent)); crust[i]=new Color32(ToByte(r.continental),ToByte(r.oceanic),ToByte(r.basin),ToByte(normShape)); } static float SmoothThreshold(float e0,float e1,float x){float t=math.saturate((x-e0)/math.max(1e-6f,e1-e0));return t*t*(3f-2f*t);} }
    [BurstCompile] struct ClimateJob:IJobParallelFor{ public int width,height; public float seed,temperature,moisture,moistureResponseScale,temperatureHumidityInfluence,climateNoiseStrength,coastWetnessStrength,continentalDrynessStrength,continentalTemperatureStrength,rainShadowStrength,orographicWetnessStrength,orographicSampleOffset,seasonalityStrength; [ReadOnly] public NativeArray<Color32> tect; [ReadOnly] public NativeArray<float> cont; public NativeArray<Color32> outp; public void Execute(int i){int x=i%width,y=i/width; float land=tect[i].r/255f,h=tect[i].g/255f,m=tect[i].b/255f,c=cont[i]; int offsetPx=math.max(1,(int)math.round(orographicSampleOffset)); float signedLat=((y+0.5f)/height)*2f-1f; float absLat=math.abs(signedLat); int windSign=absLat<0.33f?-1:1; int upwindX=(x-windSign*offsetPx+width)%width; int downwindX=(x+windSign*offsetPx+width)%width; int upwindIndex=y*width+upwindX; int downwindIndex=y*width+downwindX; float upwindMountain=tect[upwindIndex].b/255f; float downwindMountain=tect[downwindIndex].b/255f; float lat=absLat; float3 d=TexelToDir(x,y,width,height); float noise=(Fbm(d*3.1f+new float3(seed,seed*0.7f,seed*1.3f))-0.5f); float temp=math.saturate((1f-lat)+(temperature-0.5f)*0.35f-h*0.4f+c*continentalTemperatureStrength*(temperature-0.5f)+noise*climateNoiseStrength*0.2f); float baseM=math.saturate(0.5f+(moisture-0.5f)*moistureResponseScale); float moist=baseM+(1f-c)*coastWetnessStrength*land-c*continentalDrynessStrength*land+(0.5f-math.abs(temp-0.5f))*temperatureHumidityInfluence + upwindMountain*orographicWetnessStrength*land-downwindMountain*rainShadowStrength*land+m*orographicWetnessStrength*0.15f+noise*climateNoiseStrength*0.2f; float season=math.saturate((lat*0.75f+c*0.45f+noise*0.15f)*seasonalityStrength+(1f-seasonalityStrength)*0.5f); outp[i]=new Color32(ToByte(temp),ToByte(math.saturate(moist)),ToByte(c),ToByte(season)); } static float3 TexelToDir(int x,int y,int width,int height){float u=(x+0.5f)/width,v=(y+0.5f)/height;float lon=(u