    [BurstCompile] struct BiomeJob:IJobParallelFor{ [ReadOnly] public NativeArray<Color32> tect,climate,hydro; public NativeArray<Color32> o0,o1,o2; public int width,height; public float seed,biomeProvinceStrength,biomeCompetitionSharpness; public void Execute(int i){ int x=i%width,y=i/width; float3 d=TexelToDir(x,y,width,height); float land=tect[i].r/255f;if(land<0.5f){o0[i]=o1[i]=o2[i]=new Color32();return;} float h=tect[i].g/255f,mtn=tect[i].b/255f,t=climate[i].r/255f,mo=climate[i].g/255f,se=climate[i].a/255f,river=hydro[i].r/255f,lake=hydro[i].g/255f,wet=hydro[i].b/255f; float em=math.saturate(mo+river*0.12f+lake*0.2f+wet*0.35f); float provinceNoise=Fbm(d*2.4f+new float3(seed*0.19f+31.7f,seed*0.11f+84.2f,seed*0.07f+12.9f)); float province=(provinceNoise-0.5f)*2f*biomeProvinceStrength; float jungle=math.saturate((t-0.55f)*2f)*math.saturate((em-0.65f)*2f)*(1f-se*0.5f); float desert=math.saturate((1f-em)*1.6f)*math.saturate((t-0.45f)*1.8f)*(1f-wet); float sav=math.saturate((t-0.5f)*1.8f)*(1f-math.abs(em-0.5f)*2f); float tg=(1f-math.abs(t-0.52f)*2f)*(1f-math.abs(em-0.45f)*2f); float tf=(1f-math.abs(t-0.5f)*2f)*math.saturate((em-0.45f)*1.8f); float ta=(1f-math.abs(t-0.35f)*3f)*math.saturate((em-0.35f)*1.4f); float tun=math.saturate((0.4f-t)*3f); float snow=math.saturate((0.32f-t)*3f+h*0.3f+mtn*0.25f); float pol=math.saturate((0.25f-t)*4f)*math.saturate(snow+0.2f); float marsh=wet*math.saturate(em)*math.saturate(1f-snow); float alp=math.saturate((mtn*0.7f+h*0.5f)-em*0.25f); jungle*=1f+province*0.15f;desert*=1f-province*0.1f;tf*=1f+province*0.1f;tg*=1f-province*0.08f; float sh=biomeCompetitionSharpness; jungle=math.pow(math.max(0,jungle),sh);desert=math.pow(math.max(0,desert),sh);sav=math.pow(math.max(0,sav),sh);tg=math.pow(math.max(0,tg),sh);tf=math.pow(math.max(0,tf),sh);ta=math.pow(math.max(0,ta),sh);tun=math.pow(math.max(0,tun),sh);pol=math.pow(math.max(0,pol),sh);marsh=math.pow(math.max(0,marsh),sh); float sum=jungle+desert+sav+tg+tf+ta+tun+pol+marsh+1e-5f; o0[i]=